export const hubUrl = m => 'https://' + CUR_MARKT[m].host + CUR_MARKT[m].pre;

// ---------- rangschikken (ook in de browser) ----------
export function curRang(items, vragen, route, gw) {
  gw = gw == null ? 1 : gw;
  return items.map(v => {
    const r = reviewScore(v); const tags = v.tags || []; let s = gw * (r ? (r.gewogen - 3.5) * 2 : -0.5); let past = true; if (r && r.gemiddeld < 3.5 && gw >= 1) s -= 2.5;
    (vragen || []).forEach((q, qi) => { const o = (q.opties || [])[route[qi] || 0]; if (!o) return; (o.plus || []).forEach(t => { if (tags.includes(t)) s += 2; }); (o.min || []).forEach(t => { if (tags.includes(t)) s -= 1.5; }); if (o.vereist && !tags.includes(o.vereist)) { s -= 4; past = false; } });
    return { v, s: Math.round(s * 100) / 100, past, r };
  }).sort((a, b) => b.s - a.s);
}

// ---------- gedeelde opmaak (outname.now-stijl) ----------
const CSS = ':root{--bg:#fff;--panel:#fff;--ink:#111113;--body:#3A3F47;--muted:#6B7280;--line:#E5E7EB;--line-strong:#B9BFC7;--accent:#2B47C4;--accent-ink:#fff;--accent-soft:#EEF1FC;--warn:#B3261E;--warn-soft:#FCEDEB;--mid:#8A6410;--mid-soft:#FBF2DC;--ok:#1F7A4D;--ok-soft:#E8F4EE;color-scheme:light}@media (prefers-color-scheme:dark){:root{--bg:#0F1116;--panel:#161922;--ink:#F2F3F5;--body:#C9CDD3;--muted:#8B929B;--line:#272C37;--line-strong:#4A5260;--accent:#93A6FF;--accent-ink:#0B1022;--accent-soft:#1B2246;--warn:#F08A7E;--warn-soft:#3A1D1A;--mid:#E3C168;--mid-soft:#33290F;--ok:#71CF9E;--ok-soft:#16301F;color-scheme:dark}}*,*::before,*::after{box-sizing:border-box}html{-webkit-text-size-adjust:100%}body{margin:0;background:var(--bg);color:var(--body);font-family:"Inter",-apple-system,BlinkMacSystemFont,"Segoe UI",Helvetica,Arial,sans-serif;font-size:18px;line-height:1.65;-webkit-font-smoothing:antialiased;overflow-x:hidden}a{color:var(--accent)}img{max-width:100%}.top{position:sticky;top:0;z-index:5;background:var(--bg);border-bottom:1px solid var(--line)}.top-in{max-width:1040px;margin:0 auto;padding:16px 26px;display:flex;align-items:center;gap:16px;flex-wrap:wrap}.brand{font-weight:700;letter-spacing:-.02em;font-size:20px;color:var(--ink);text-decoration:none}.brand span{color:var(--accent)}.kruim{font-size:14px;color:var(--muted);text-decoration:none}.kruim:hover{color:var(--accent)}.langs{margin-left:auto;display:flex;gap:2px;font-size:14px;font-weight:600}.langs a{color:var(--muted);text-decoration:none;padding:4px 7px;border-radius:6px}.langs a[aria-current]{color:var(--accent)}main{max-width:820px;margin:0 auto;padding:52px 26px 30px}.eyebrow{font-size:12px;font-weight:600;letter-spacing:1.4px;text-transform:uppercase;color:var(--muted);margin:0 0 8px;display:flex;align-items:center;gap:9px}.live-dot{width:7px;height:7px;background:var(--accent);border-radius:50%;display:inline-block;flex:none}h1{font-size:clamp(32px,6vw,54px);line-height:1.09;letter-spacing:-.04em;color:var(--ink);margin:16px 0 20px;font-weight:700;text-wrap:balance;overflow-wrap:break-word}h2{font-size:30px;line-height:1.22;letter-spacing:-.03em;color:var(--ink);margin:8px 0 14px;font-weight:700;text-wrap:balance}h3{color:var(--ink);font-weight:600;margin:0}p{margin:0 0 14px}.lead{font-size:20px;line-height:1.7;max-width:660px;margin-bottom:28px}.vragen{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px 16px;border:1px solid var(--line);border-radius:16px;box-shadow:0 5px 22px #15214b08;padding:22px;margin:0 0 12px}.field{min-width:0}.field label{display:block;font-size:15px;font-weight:600;color:var(--ink);margin:0 0 7px}.field select{width:100%;min-height:50px;border:1px solid var(--line-strong);border-radius:9px;background:var(--bg);color:var(--ink);font:inherit;font-size:17px;padding:10px 12px}.micro,.fine{font-size:15px;color:var(--muted);line-height:1.6}section{padding:56px 0 0}.top3{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:15px;margin:22px 0 0}.kaart{border:1px solid var(--line);border-radius:14px;padding:22px 20px;display:flex;flex-direction:column;background:var(--panel);min-width:0}#ah-top .kaart:first-child{border-color:var(--accent)}.kaart h3{font-size:20px;line-height:1.3;margin:4px 0 10px;overflow-wrap:break-word}.score{font-size:32px;font-weight:700;letter-spacing:-1px;color:var(--ink);margin:0 0 6px;line-height:1.1}.score small{font-size:14px;font-weight:400;letter-spacing:0;color:var(--muted);margin-left:6px}.score.leeg{font-size:16px;font-weight:400;color:var(--muted);letter-spacing:0}.feiten{font-size:15px;color:var(--muted);line-height:1.6;margin:0 0 14px}.pm{list-style:none;padding:0;margin:0 0 16px;font-size:16px;line-height:1.6}.pm li{position:relative;padding-left:18px;margin:5px 0}.pm li::before{position:absolute;left:0;font-weight:700}.pm .p::before{content:"+";color:var(--ok)}.pm .m::before{content:"−";color:var(--warn)}.kaart .pm{flex:1}.cta{display:inline-block;border:0;background:var(--accent);color:var(--accent-ink);border-radius:9px;padding:12px 16px;font-weight:600;font-size:15px;text-decoration:none;text-align:center}.cta.ghost{background:transparent;color:var(--accent);box-shadow:inset 0 0 0 1.5px var(--accent)}.lijst{margin-top:18px;border-top:1px solid var(--line)}.line{padding:18px 0;border-bottom:1px solid var(--line)}.line-top{display:flex;align-items:flex-start;justify-content:space-between;gap:14px}.line-top>div{min-width:0}.lname{font-size:19px;line-height:1.35;overflow-wrap:break-word}.lname a{color:var(--ink);text-decoration:none}.lname a:hover{color:var(--accent)}.lsub{font-size:15px;color:var(--muted);line-height:1.6;margin-top:3px}.badge{font-size:15px;font-weight:600;border-radius:999px;padding:4px 11px;white-space:nowrap;font-variant-numeric:tabular-nums;flex:none}.badge small{font-weight:400;opacity:.75;margin-left:2px}.b-goed{background:var(--ok-soft);color:var(--ok)}.b-mid{background:var(--mid-soft);color:var(--mid)}.b-slecht{background:var(--warn-soft);color:var(--warn)}.b-leeg{background:var(--line);color:var(--muted)}.line .pm{margin:10px 0 0}details{border-top:1px solid var(--line);padding:14px 0}details:last-of-type{border-bottom:1px solid var(--line)}summary{cursor:pointer;color:var(--ink);font-weight:600;font-size:17px}details p{font-size:16px;line-height:1.8;color:var(--muted);margin:8px 0 0}details.mini{border:0;padding:6px 0 0}details.mini summary{font-size:14px;font-weight:500;color:var(--muted)}details.mini .pm{margin-top:6px}.zonder{margin-top:10px}.vak{background:var(--accent-soft);border-radius:16px;padding:28px 30px}.vak ul{margin:0;padding-left:18px;font-size:16px;line-height:1.8}.vak li{margin:0 0 8px}.bronnen li{font-size:14px;overflow-wrap:anywhere}.hub{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px;margin:20px 0 0}.tegel{display:flex;flex-direction:column;gap:6px;border:1px solid var(--line);border-radius:14px;padding:20px 20px 18px;text-decoration:none;color:var(--body);background:var(--panel);transition:border-color .15s}.tegel:hover{border-color:var(--accent)}.tegel h3{font-size:19px}.tegel p{margin:0;font-size:15px;color:var(--muted);line-height:1.55}.tegel .meer{margin-top:auto;padding-top:8px;font-size:14px;font-weight:600;color:var(--accent)}.tegel.uit{opacity:.55;pointer-events:none}footer{border-top:1px solid var(--line);margin-top:40px}footer .in{max-width:820px;margin:0 auto;padding:22px 26px 40px;font-size:14px;color:var(--muted)}footer a{color:var(--muted)}@media(max-width:760px){.top3{grid-template-columns:1fr}.hub{grid-template-columns:1fr}}@media(max-width:640px){.top-in{padding:14px 16px;flex-wrap:nowrap;gap:10px}.brand{font-size:17px;white-space:nowrap}.kruim{font-size:13px;white-space:nowrap}.langs a{padding:4px 3px;font-size:12px}main{padding:34px 18px 20px}.vragen{grid-template-columns:1fr;padding:18px}h2{font-size:26px}.lead{font-size:18px}.vak{padding:22px}section{padding-top:44px}.line-top{flex-direction:column;gap:8px}.badge{align-self:flex-start}}';

function kop(m, M, titel, desc, canon, alts, schema) {
  return '<!doctype html><html lang="' + M.lang + '"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>' + esc(titel) + '</title><meta name="description" content="' + esc(desc) + '"><meta name="robots" content="index,follow,max-snippet:-1,max-image-preview:large"><link rel="canonical" href="' + canon + '">'
    + alts.map(([l, u]) => '<link rel="alternate" hreflang="' + l + '" href="' + u + '">').join('') + '<link rel="alternate" hreflang="x-default" href="' + (alts.find(a => a[0] === 'en') || alts[0])[1] + '">'
    + '<meta property="og:title" content="' + esc(titel) + '"><meta property="og:description" content="' + esc(desc) + '"><meta property="og:url" content="' + canon + '"><meta property="og:type" content="article"><meta property="og:locale" content="' + M.locale.replace('-', '_') + '">'
    + '<script type="application/ld+json">' + JSON.stringify(schema).replace(/</g, '\\u003c') + '</script><style>' + CSS + '</style></head><body>';
}
const balk = (m, kruim, talen) => '<header class="top"><div class="top-in"><a class="brand" href="/">' + CUR_MARKT[m].merk + '</a>' + (kruim ? '<a class="kruim" href="' + kruim[0] + '">' + esc(kruim[1]) + '</a>' : '') + '<nav class="langs" aria-label="Language">' + talen + '</nav></div></header>';
const talenNav = (m, urlVan) => Object.keys(CUR_MARKT).map(k => '<a href="' + urlVan(k) + '" hreflang="' + k + '"' + (k === m ? ' aria-current="true"' : '') + '>' + k.toUpperCase() + '</a>').join('');
const voet = (m, d) => '</main><footer><div class="in">' + esc(T[m].mis) + ' <a href="mailto:henkjan@keuzehulp.best">henkjan@keuzehulp.best</a> · Henkjan de Krijger, ' + esc(d) + '<br>' + esc(CUR_MARKT[m].naam) + ' · AdsFair B.V., Gouda · KvK 60126035 · <a href="' + hubUrl(m) + '">' + esc(T[m].home) + '</a> · <a href="/privacy">Privacy</a></div></footer>';
// meting in de browser: bron van het bezoek (zoekmachine/AI/overig), keuzes en uitgaande kliks
export const meetJs = (m, pagina) => '(function(){function bron(){var r=document.referrer||"",u=location.search;if(/utm_source=(chatgpt|openai|perplexity|copilot|gemini|claude)/i.test(u))return "ai";try{var h=r?new URL(r).hostname:"";if(!h||h===location.hostname)return h?"intern":"direct";if(/chatgpt|openai|perplexity|copilot|gemini\\.google|claude\\.ai|you\\.com|phind/.test(h))return "ai";if(/google\\.|bing\\.|duckduckgo|yahoo\\.|ecosia|qwant|startpage|yandex|brave/.test(h))return "zoek";return "overig"}catch(e){return "overig"}}function hit(k){try{var d=new Date().toISOString().slice(0,10).replace(/-/g,"");navigator.sendBeacon("/api/keuze-tools?tool=cur&op=hit",new Blob([JSON.stringify({m:"' + m + '",p:"' + pagina + '",k:k})],{type:"text/plain"}))}catch(e){}}window.__curHit=hit;hit("view-"+bron());document.addEventListener("click",function(e){var a=e.target.closest&&e.target.closest("a[data-out]");if(a)hit("out-"+a.getAttribute("data-out"))})})();';

// ---------- voorpagina ----------
export function renderHub(m) {
  const M = CUR_MARKT[m], t = T[m], d = DATUM('2026-10-20', m), url = hubUrl(m);
  const tegel = o => { const dd = dataVan(o); const n = o.id === 'autohuur' ? AUTOHUUR_DATA.verhuurders.length : (dd && dd.items || []).length; const aan = actief(o); return '<a class="tegel' + (aan ? '' : ' uit') + '" href="' + (aan ? curUrl(m, o) : '#') + '"' + (aan ? '' : ' aria-disabled="true"') + '><h3>' + esc(tx(o.label, m)) + '</h3><p>' + esc(tx(o.sub, m)) + '</p><span class="meer">' + (aan ? esc(t.vergeleken(n)) + ' →' : esc(t.binnenkort)) + '</span></a>'; };
  const groep = g => ONDERWERPEN.filter(o => o.groep === g);
  const actieve = ONDERWERPEN.filter(actief);
  const schema = { '@context': 'https://schema.org', '@graph': [
    { '@type': 'CollectionPage', name: t.hubH1, description: t.hubLead, inLanguage: M.lang, url, dateModified: '2026-10-20', author: { '@type': 'Person', name: 'Henkjan de Krijger', url: 'https://www.linkedin.com/in/henkjandekrijger' }, about: { '@type': 'Place', name: 'Curaçao' } },
    { '@type': 'ItemList', itemListElement: actieve.map((o, i) => ({ '@type': 'ListItem', position: i + 1, name: tx(o.label, m), url: curUrl(m, o) })) },
    { '@type': 'BreadcrumbList', itemListElement: [{ '@type': 'ListItem', position: 1, name: M.naam, item: 'https://' + M.host + '/' }, { '@type': 'ListItem', position: 2, name: t.home, item: url }] }] };
  return kop(m, M, t.hubTitel + ' | ' + M.naam, t.hubLead, url, Object.keys(CUR_MARKT).map(k => [k, hubUrl(k)]), schema) + balk(m, null, talenNav(m, hubUrl)) + '<main>'
    + '<p class="eyebrow"><span class="live-dot"></span>' + esc(t.peil) + ' ' + esc(d) + '</p><h1>' + esc(t.hubH1) + '</h1><p class="lead">' + esc(t.hubLead) + '</p>'
    + '<section style="padding-top:20px"><p class="eyebrow">' + esc(t.reis) + '</p><div class="hub">' + groep('reis').map(tegel).join('') + '</div></section>'
    + '<section><p class="eyebrow">' + esc(t.wonen) + '</p><div class="hub">' + groep('wonen').map(tegel).join('') + '</div></section>'
    + '<section><h2>' + esc(t.methode) + '</h2><p class="fine">' + esc(t.methodeTekst) + '</p></section>'
    + voet(m, d) + '<script>' + meetJs(m, 'hub') + '</script></body></html>';
}

// ---------- pagina per onderwerp ----------
export function renderOnderwerp(m, o, route) {
  const M = CUR_MARKT[m], t = T[m], D = dataVan(o), items = D.items || [], n = items.length, d = DATUM(D.peildatum, m), url = curUrl(m, o);
  const vr = D.vragen || []; route = vr.map((q, i) => Math.max(0, Math.min((q.opties || []).length - 1, route[i] || 0)));
  const GW = D.reviewGewicht == null ? 1 : D.reviewGewicht; const rang = curRang(items, vr, route, GW); const top = rang.slice(0, 3);
  const getal = (x, dd) => Number(x).toLocaleString(M.locale, { minimumFractionDigits: dd || 0, maximumFractionDigits: dd == null ? 2 : dd });
  const geld = p => (p.valuta === 'EUR' ? '€' : p.valuta === 'XCG' || p.valuta === 'ANG' ? 'XCG ' : '$') + getal(p.bedrag, p.bedrag % 1 ? 2 : 0) + (p.eenheid ? ' ' + tx(p.eenheid, m) : '');
  const kort = v => [tx(v.soort, m), v.plaats, v.prijs ? geld(v.prijs) : '', ...(v.feiten || []).map(f => tx(f, m))].filter(Boolean).map(esc).join(' · ');
  const scoresTxt = v => (v.scores || []).filter(x => x.score).map(x => esc(x.platform) + ' ' + getal(x.score, 1) + (x.max && x.max !== 5 ? '/' + x.max : '') + (x.aantal ? ' (' + getal(x.aantal, 0) + ')' : '')).join(' · ') || t.geenRev;
  const kleur = r => !r ? 'b-leeg' : r.gemiddeld >= 4.5 ? 'b-goed' : r.gemiddeld >= 3.5 ? 'b-mid' : 'b-slecht';
  const lijst = v => [tx(v.voor, m) || [], tx(v.tegen, m) || []].map(a => Array.isArray(a) ? a : []);
  const naamLink = v => v.url ? '<a href="' + esc(v.url) + '" target="_blank" rel="noopener nofollow" data-out="' + esc(v.id) + '">' + esc(v.naam) + '</a>' : esc(v.naam);
  const kaart = (x, i) => { const v = x.v; const [vo, te] = lijst(v); return '<article class="kaart ah-kaart" data-id="' + esc(v.id) + '"><p class="eyebrow"><span class="kicker">' + (i + 1) + '. ' + esc(tx(v.soort, m)) + '</span></p><h3>' + esc(v.naam) + '</h3>' + (x.r ? '<p class="score">' + getal(x.r.gemiddeld, 1) + '<small>★ · ' + getal(x.r.aantal, 0) + ' ' + t.reviewsW + '</small></p>' : '<p class="score leeg">' + t.geenRev + '</p>') + '<p class="feiten">' + kort(v) + '</p><ul class="pm">' + vo.slice(0, 2).map(a => '<li class="p">' + esc(a) + '</li>').join('') + te.slice(0, 1).map(a => '<li class="m">' + esc(a) + '</li>').join('') + '</ul>' + (v.url ? '<a class="cta ghost" href="' + esc(v.url) + '" target="_blank" rel="noopener nofollow" data-out="' + esc(v.id) + '">' + t.bekijk + ' →</a>' : '') + '</article>'; };
  const rij = x => { const v = x.v; const [vo, te] = lijst(v); const veel = vo.length > 1 || te.length > 1 || (v.scores || []).length > 1; return '<article class="line ah-r" data-id="' + esc(v.id) + '"><div class="line-top"><div><h3 class="lname">' + naamLink(v) + '</h3><div class="lsub">' + kort(v) + '</div></div><span class="badge ' + kleur(x.r) + '">' + (x.r ? getal(x.r.gemiddeld, 1) + ' ★ <small>' + getal(x.r.aantal, 0) + '</small>' : '–') + '</span></div>' + (vo[0] || te[0] ? '<ul class="pm">' + (vo[0] ? '<li class="p">' + esc(vo[0]) + '</li>' : '') + (te[0] ? '<li class="m">' + esc(te[0]) + '</li>' : '') + '</ul>' : '') + (veel ? '<details class="mini"><summary>' + t.meer + '</summary><ul class="pm">' + vo.slice(1).map(a => '<li class="p">' + esc(a) + '</li>').join('') + te.slice(1).map(a => '<li class="m">' + esc(a) + '</li>').join('') + '</ul><p class="fine">' + scoresTxt(v) + '</p></details>' : '') + '</article>'; };
  const vragen = vr.map((q, qi) => '<div class="field"><label for="ah-q' + qi + '">' + esc(tx(q.q, m)) + '</label><select id="ah-q' + qi + '" name="q' + qi + '">' + (q.opties || []).map((op, oi) => '<option value="' + oi + '"' + (route[qi] === oi ? ' selected' : '') + '>' + esc(tx(op.label, m)) + '</option>').join('') + '</select></div>').join('');
  const faq = (D.faq || []).map(f => [tx(f.q, m), tx(f.a, m)]).filter(f => f[0] && f[1]);
  const tips = (D.tips || []).map(x => tx(x, m)).filter(Boolean);
  const bronnen = [...new Set(items.flatMap(v => v.bronnen || []))].slice(0, 100);
  const vul = s => String(s || '').replace(/\{n\}/g, n);
  const titel = vul(tx(D.titel, m)) || tx(o.label, m), desc = vul(tx(D.metaDesc, m)) || vul(tx(D.kort, m)), h1 = tx(D.h1, m) || tx(o.label, m), kortTxt = vul(tx(D.kort, m));
  const alts = Object.keys(CUR_MARKT).map(k => [k, curUrl(k, o)]);
  const schema = { '@context': 'https://schema.org', '@graph': [
    { '@type': 'Article', headline: h1, description: desc, inLanguage: M.lang, datePublished: D.peildatum, dateModified: D.peildatum, mainEntityOfPage: url, author: { '@type': 'Person', name: 'Henkjan de Krijger', url: 'https://www.linkedin.com/in/henkjandekrijger' }, publisher: { '@type': 'Organization', name: M.naam }, about: { '@type': 'Place', name: 'Curaçao' } },
    { '@type': 'ItemList', name: t.alle, numberOfItems: n, itemListElement: rang.map((x, i) => ({ '@type': 'ListItem', position: i + 1, name: x.v.naam, url: x.v.url || undefined })) },
    { '@type': 'BreadcrumbList', itemListElement: [{ '@type': 'ListItem', position: 1, name: M.naam, item: 'https://' + M.host + '/' }, { '@type': 'ListItem', position: 2, name: t.home, item: hubUrl(m) }, { '@type': 'ListItem', position: 3, name: tx(o.label, m), item: url }] },
    ...(faq.length ? [{ '@type': 'FAQPage', mainEntity: faq.map(([q, a]) => ({ '@type': 'Question', name: q, acceptedAnswer: { '@type': 'Answer', text: a } })) }] : [])] };
  const zonder = rang.filter(x => !x.r);
  const client = '(function(){var GW=' + GW + ',D=' + JSON.stringify(items.map(v => ({ id: v.id, tags: v.tags || [], scores: v.scores || [] }))) + ',V=' + JSON.stringify(vr.map(q => ({ opties: (q.opties || []).map(op => ({ plus: op.plus || [], min: op.min || [], vereist: op.vereist || null })) }))) + ';' + reviewScore.toString() + ';' + curRang.toString() + ';var top=document.getElementById("ah-top"),st=document.getElementById("ah-store"),kaarten={},rijen={};document.querySelectorAll(".ah-kaart").forEach(function(k){kaarten[k.dataset.id]=k});document.querySelectorAll(".ah-r").forEach(function(r){rijen[r.dataset.id]=r});function go(){var r=V.map(function(q,i){return +document.getElementById("ah-q"+i).value});var x=curRang(D,V,r,GW);top.querySelectorAll(".ah-kaart").forEach(function(k){st.appendChild(k)});x.slice(0,3).forEach(function(y,i){var k=kaarten[y.v.id];if(k){var kk=k.querySelector(".kicker");kk.textContent=(i+1)+". "+kk.textContent.replace(/^\\d+\\. /,"");top.appendChild(k)}});x.forEach(function(y){var rr=rijen[y.v.id];if(rr)rr.parentNode.appendChild(rr)});document.getElementById("ah-geen").hidden=!!(x[0]&&x[0].past);if(window.__curHit)window.__curHit("route-"+r.join(""))}V.forEach(function(q,i){document.getElementById("ah-q"+i).addEventListener("change",go)})})();';
  const store = rang.slice(3).map((x, i) => kaart(x, i + 3)).join('');
  return kop(m, M, titel, desc, url, alts, schema) + balk(m, [hubUrl(m), '← ' + t.home], talenNav(m, k => curUrl(k, o))) + '<main>'
    + '<p class="eyebrow"><span class="live-dot"></span>' + esc(t.peil) + ' ' + esc(d) + ' · ' + esc(t.vergeleken(n)) + '</p><h1>' + esc(h1) + '</h1>' + (kortTxt ? '<p class="lead">' + esc(kortTxt) + '</p>' : '')
    + (vr.length ? '<form id="ah-form" class="vragen" method="get" action="' + url.replace(/^https:\/\/[^/]+/, '') + '" onsubmit="return false">' + vragen + '</form><p class="micro">' + esc(t.klik) + '</p>' : '')
    + '<section><p class="eyebrow">' + esc(t.jouw) + '</p><p id="ah-geen" class="micro"' + (top[0] && top[0].past ? ' hidden' : '') + '>' + esc(t.geen) + '</p><div id="ah-top" class="top3">' + top.map(kaart).join('') + '</div><div id="ah-store" hidden>' + store + '</div></section>'
    + '<section><h2>' + esc(t.alle) + '</h2><div class="lijst">' + rang.filter(x => x.r).map(rij).join('') + '</div>' + (zonder.length ? '<details class="zonder"><summary>' + esc(t.zonderRev) + ' (' + zonder.length + ')</summary><div>' + zonder.map(rij).join('') + '</div></details>' : '') + '<p class="fine" style="margin-top:16px">' + esc(t.prijsNoot) + '</p></section>'
    + ((D.tussenpartijen || []).length ? '<section><h2>' + esc(t.tussen) + '</h2><div class="lijst">' + D.tussenpartijen.map(b => { const u = tx(b.uitleg, m); return '<div class="line"><h3 class="lname">' + (b.url ? '<a href="' + esc(b.url) + '" target="_blank" rel="noopener nofollow" data-out="tp-' + esc(String(b.naam).toLowerCase().replace(/[^a-z0-9]+/g, '-')) + '">' + esc(b.naam) + '</a>' : esc(b.naam)) + '</h3>' + (u ? '<div class="lsub">' + esc(Array.isArray(u) ? u.slice(0, 2).join(' ') : u) + '</div>' : '') + '</div>'; }).join('') + '</div></section>' : '')
    + (tips.length ? '<section><div class="vak"><p class="eyebrow">' + esc(t.tips) + '</p><ul>' + tips.map(x => '<li>' + esc(x) + '</li>').join('') + '</ul></div></section>' : '')
    + (faq.length ? '<section><h2>' + esc(t.faq) + '</h2>' + faq.map(([q, a]) => '<details><summary>' + esc(q) + '</summary><p>' + esc(a) + '</p></details>').join('') + '</section>' : '')
    + '<section><h2>' + esc(t.methode) + '</h2><p class="fine">' + esc(t.methodeTekst) + '</p><details><summary>' + esc(t.bronnen) + ' (' + bronnen.length + ')</summary><ul class="bronnen">' + bronnen.map(b => '<li><a href="' + esc(b) + '" rel="nofollow noopener" target="_blank">' + esc(String(b).replace(/^https?:\/\/(www\.)?/, '').slice(0, 90)) + '</a></li>').join('') + '</ul></details></section>'
    + voet(m, d) + '<script>' + meetJs(m, o.id) + '</script><script>' + client + '</script></body></html>';
}

// ---------- items voor sitemap, llms.txt en overzichten ----------
export function curItems(markt) { // markt: nl | us | de  (whichtobuy.best krijgt ook es en pt)
  const ms = markt === 'nl' ? ['nl'] : markt === 'de' ? ['de'] : ['en', 'es', 'pt'];
  const out = [];
  for (const m of ms) {
    const t = T[m], pad = u => u.replace(/^https:\/\/[^/]+\//, '');
    if (ONDERWERPEN.filter(actief).length >= 4) out.push({ slug: pad(hubUrl(m)), title: t.hubH1, h1: t.hubH1, seoTitle: t.hubTitel, metaDesc: t.hubLead, cat: m === 'nl' ? 'Reizen' : m === 'de' ? 'Reisen' : 'Travel', term: 'Curaçao', intro: t.hubLead, kort: t.hubLead, questions: [], uitleg: '', guide: '', fouten: [], faq: [], publishAt: '2026-10-20', updatedAt: '2026-10-20', tool: true, priority: 98 });
    for (const o of ONDERWERPEN) {
      if (o.vast && o.vast[m]) continue; if (!actief(o)) continue; const D = dataVan(o); const n = (D.items || []).length; const vul = s => String(s || '').replace(/\{n\}/g, n);
      out.push({ slug: pad(curUrl(m, o)), title: tx(D.h1, m) || tx(o.label, m), h1: tx(D.h1, m) || tx(o.label, m), seoTitle: vul(tx(D.titel, m)), metaDesc: vul(tx(D.metaDesc, m)), cat: m === 'nl' ? 'Reizen' : m === 'de' ? 'Reisen' : 'Travel', term: tx(o.label, m), intro: vul(tx(D.kort, m)), kort: vul(tx(D.kort, m)), questions: (D.vragen || []).map(q => ({ q: tx(q.q, m), options: (q.opties || []).map(op => ({ label: tx(op.label, m) })) })), uitleg: (D.tips || []).map(x => tx(x, m)).join('\n\n'), guide: (D.tips || []).map(x => tx(x, m)).join('\n\n'), fouten: [], faq: (D.faq || []).map(f => ({ q: tx(f.q, m), a: tx(f.a, m) })), publishAt: D.peildatum, updatedAt: D.peildatum, tool: true, priority: 96 });
    }
  }
  return out;
}
export const alleCurUrls = () => Object.keys(CUR_MARKT).flatMap(m => [hubUrl(m), ...ONDERWERPEN.filter(actief).map(o => curUrl(m, o))]);

// ---------- meting ----------
const DAG = () => new Date().toISOString().slice(0, 10);
const BOTS = [['gptbot', /GPTBot/i], ['oai-search', /OAI-SearchBot/i], ['chatgpt-user', /ChatGPT-User/i], ['perplexity', /Perplexity/i], ['claude', /Claude(Bot|-User|-SearchBot)|anthropic/i], ['google-ext', /Google-Extended/i], ['googlebot', /Googlebot/i], ['bingbot', /bingbot/i], ['applebot', /Applebot/i], ['meta', /meta-externalagent|facebookexternalhit/i]];
export async function telBot(req, m, p) { const ua = String(req.headers['user-agent'] || ''); const b = BOTS.find(x => x[1].test(ua)); if (!b) return; try { await kv.incrMany([['cur:bot:' + DAG() + ':' + b[0], 1], ['cur:botp:' + DAG() + ':' + m + ':' + p + ':' + b[0], 1]]); } catch (e) {} }
async function hit(req, res) {
  let b = req.body; if (typeof b === 'string') { try { b = JSON.parse(b); } catch (e) { b = {}; } } if (!b || typeof b !== 'object') { try { const raw = await new Promise(r => { let s = ''; req.on('data', c => { s += c; if (s.length > 2000) req.destroy(); }); req.on('end', () => r(s)); }); b = JSON.parse(raw || '{}'); } catch (e) { b = {}; } }
  const m = CUR_MARKT[b.m] ? b.m : null; const p = String(b.p || '').replace(/[^a-z0-9-]/g, '').slice(0, 30); const k = String(b.k || '').replace(/[^a-z0-9-]/g, '').slice(0, 50);
  if (!m || !p || !k) return res.status(204).end();
  try { await kv.incrMany([['cur:h:' + DAG() + ':' + m + ':' + p + ':' + k, 1], ['cur:t:' + DAG() + ':' + k.split('-').slice(0, 2).join('-'), 1]]); } catch (e) {}
  return res.status(204).end();
}
export async function curStand(dagen) {
  dagen = Math.min(30, dagen || 7); const uit = []; const vandaag = new Date();
  for (let i = 0; i < dagen; i++) {
    const d = new Date(vandaag.getTime() - i * 864e5).toISOString().slice(0, 10); const rij = { dag: d, bezoek: {}, bots: {}, perPagina: {} };
    let cur = '0'; let n = 0; do { const [c, keys] = await kv.scan(cur, { match: 'cur:h:' + d + ':*', count: 500 }); cur = c; if (keys.length) { const vals = await kv.mget(...keys); keys.forEach((k, j) => { const [, , , m, p, kk] = k.split(':'); const v = Number(vals[j]) || 0; if (kk.startsWith('view-')) { rij.bezoek[kk.slice(5)] = (rij.bezoek[kk.slice(5)] || 0) + v; const key = m + '/' + p; rij.perPagina[key] = (rij.perPagina[key] || 0) + v; } else { rij[kk.split('-')[0]] = (rij[kk.split('-')[0]] || 0) + v; } }); } n++; } while (cur !== '0' && n < 20);
    cur = '0'; n = 0; do { const [c, keys] = await kv.scan(cur, { match: 'cur:bot:' + d + ':*', count: 200 }); cur = c; if (keys.length) { const vals = await kv.mget(...keys); keys.forEach((k, j) => { rij.bots[k.split(':').pop()] = Number(vals[j]) || 0; }); } n++; } while (cur !== '0' && n < 10);
    uit.push(rij);
  }
  const llm = await kv.get('cur:llm:laatste').catch(() => null);
  return { dagen: uit, llm };
}
// AI-vermeldingen: per ronde 8 vragen (roterend over onderwerpen en talen) aan Perplexity; genoemd = een van onze domeinen staat in de bronnen
export async function curLLM(oidc) {
  const { meetLLM } = await import('./zicht.js'); const vragen = [];
  for (const o of ONDERWERPEN) { const D = dataVan(o); const lv = (D && D.llmVragen) || {}; for (const m of ['nl', 'en']) for (const v of (lv[m] || []).slice(0, 2)) vragen.push({ o: o.id, m, v }); }
  if (!vragen.length) return { leeg: true };
  const start = Number(await kv.get('cur:llm:pos').catch(() => 0)) || 0; const deze = Array.from({ length: Math.min(8, vragen.length) }, (_, i) => vragen[(start + i) % vragen.length]);
  const res = [];
  for (const x of deze) { const host = x.m === 'nl' ? 'keuzehulp.best' : 'whichtobuy.best'; const [r] = await meetLLM({ host, taal: x.m, soort: 'keuzehulp', merk: [host] }, [x.v], oidc); res.push(Object.assign({ onderwerp: x.o, taal: x.m }, r)); }
  await kv.set('cur:llm:pos', (start + deze.length) % vragen.length);
  const log = (await kv.get('cur:llm:log').catch(() => null)) || []; const rec = { at: new Date().toISOString(), res }; log.unshift({ at: rec.at, genoemd: res.filter(r => r.genoemd).length, van: res.length });
  await kv.set('cur:llm:log', log.slice(0, 60)); await kv.set('cur:llm:laatste', rec);
  return rec;
}
export async function curPing(force) {
  const k = 'cur:ping:' + DAG(); if (!force && await kv.get(k).catch(() => null)) return { overgeslagen: true };
  const sleutels = { 'keuzehulp.best': '466971cbc1bbe43e6bb64a94465e4470', 'whichtobuy.best': '7c1e4b9a2f6d48e3a05b9c71d2e8f4a6', 'kaufberater.best': '7c1e4b9a2f6d48e3a05b9c71d2e8f4a6' }; const per = {};
  for (const u of alleCurUrls()) { const h = new URL(u).hostname; (per[h] = per[h] || []).push(u); }
  const uit = {};
  for (const [h, urls] of Object.entries(per)) { try { const r = await fetch('https://api.indexnow.org/indexnow', { method: 'POST', headers: { 'content-type': 'application/json; charset=utf-8' }, body: JSON.stringify({ host: h, key: sleutels[h], keyLocation: 'https://' + h + '/' + sleutels[h] + '.txt', urlList: [...urls, 'https://' + h + '/sitemap.xml'] }) }); uit[h] = r.status + ' (' + urls.length + ')'; } catch (e) { uit[h] = String(e.message || e).slice(0, 60); } }
  await kv.set(k, uit, { ex: 2 * 86400 }).catch(() => {}); return uit;
}

export async function curHandler(req, res, url) {
  const q = url.searchParams; const op = q.get('op') || '';
  if (op === 'hit') return hit(req, res);
  if (op === 'stand') { res.setHeader('cache-control', 'no-store'); return res.status(200).json(await curStand(Number(q.get('dagen')) || 7)); }
  if (op === 'llm') { res.setHeader('cache-control', 'no-store'); const k = 'cur:llmrun:' + DAG(); const n = await kv.incr(k).catch(() => 1); if (n === 1) await kv.raw(['EXPIRE', k, 2 * 86400]).catch(() => {}); if (n > 3) return res.status(429).json({ error: 'al 3 rondes vandaag' }); return res.status(200).json(await curLLM(String(req.headers['x-vercel-oidc-token'] || ''))); }
  if (op === 'ping') return res.status(200).json(await curPing(q.get('force') === '1'));
  if (op === 'urls') return res.status(200).json(alleCurUrls());
  if (!['GET', 'HEAD'].includes(req.method || 'GET')) return res.status(405).send('Method not allowed');
  const m = CUR_MARKT[q.get('m')] ? q.get('m') : 'en'; const s = String(q.get('s') || '').toLowerCase();
  res.setHeader('content-type', 'text/html; charset=utf-8'); res.setHeader('cache-control', 'public, max-age=600');
  if (!s) { await telBot(req, m, 'hub'); return res.status(200).send(renderHub(m)); }
  const o = ONDERWERPEN.find(x => x.slug[m] === s);
  if (!o) return res.status(404).send('Not found');
  if (o.vast && o.vast[m]) { res.setHeader('location', o.vast[m]); return res.status(308).end(); }
  if (!actief(o)) { res.setHeader('location', hubUrl(m)); return res.status(307).end(); }
  await telBot(req, m, o.id);
  const route = (dataVan(o).vragen || []).map((_, i) => parseInt(q.get('q' + i) || '0', 10) || 0);
  return res.status(200).send(renderOnderwerp(m, o, route));
}
